if ( ! function_exists( 'dkds_is' ) ) {
    function dkds_is() { return is_singular( 'post' ) && has_category( 'doc-sau' ); }
    add_filter( 'body_class', function ( $c ) { if ( dkds_is() ) { $c[] = 'dkds'; } return $c; } );
    add_action( 'wp_head', function () {
        if ( ! dkds_is() ) { return; }
        echo '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:wght@900&amp;family=Newsreader:opsz,wght@6..72,400&amp;display=swap">' . "\n";
        echo '<style id="dkds-css">' . DKDS_CSS . '</style>' . "\n";
    }, 99 );
    add_action( 'wp_footer', function () {
        if ( ! dkds_is() ) { return; }
        echo '<div class="ds-rb" aria-hidden="true">' . DKDS_ICON . '<span class="l">ĐỌC SÂU</span><span class="c"></span><span class="r"></span><span class="p"></span></div>';
        echo '<script id="dkds-js">' . DKDS_JS . '</script>';
    }, 99 );
